### Impact

Anyone on the internet can inject script that executes in the Contao back end origin, under the session of whichever user opens the Comments module, with no click and no hover. From there the payload acts as that user through the back end: reading any module they can reach, creating a new administrator, or editing a template, which on Contao is a documented path from back end write access to code execution. Moderation does not help and in fact guarantees exposure, since unpublished comments are still inserted and a moderator has to open the list to act on them.", "ghsa_id": "GHSA-628f-v4f6-p37r", "github_reviewed_at": "2026-10-09T20:53:50Z", "html_url": "https://github.com/advisories/GHSA-628f-v4f6-p37r", "identifiers": [{"type": "GHSA", "value": "GHSA-628f-v4f6-p37r"}, {"type": "CVE", "value": "CVE-2026-107845"}], "nvd_published_at": null, "published_at": "2026-10-09T20:53:50Z", "references": ["https://github.com/contao/contao/security/advisories/GHSA-628f-v4f6-p37r", "https://github.com/contao/contao/commit/22505d5f79bc1a7f52e2cba5fddf6007e1f0408a", "https://github.com/contao/contao/releases/tag/5.3.50", "https://github.com/contao/contao/releases/tag/5.7.12", "https://github.com/advisories/GHSA-628f-v4f6-p37r"], "repository_advisory_url": "https://api.github.com/repos/contao/contao/security-advisories/GHSA-628f-v4f6-p37r", "severity": "critical", "source_code_location": "https://github.com/contao/contao", "summary": "Contao: Cross-site scripting in the comments bundle", "type": "reviewed", "updated_at": "2026-10-09T20:53:52Z", "url": "https://api.github.com/advisories/GHSA-628f-v4f6-p37r", "vulnerabilities": [{"first_patched_version": "5.3.50", "package": {"ecosystem": "composer", "name": "contao/comments-bundle"}, "vulnerable_functions": [], "vulnerable_version_range": ">= 4.0.0, < 5.3.50"}, {"first_patched_version": "5.7.12", "package": {"ecosystem": "composer", "name": "contao/comments-bundle"}, "vulnerable_functions": [], "vulnerable_version_range": ">= 5.4.0-